import{c as a,Q as t,j as i,m as o}from"./chunks/framework.W-g_WCNV.js";const u=JSON.parse('{"title":"Changelog","description":"Version history for GateKeeper.","frontmatter":{"title":"Changelog","description":"Version history for GateKeeper."},"headers":[],"relativePath":"reference/changelog.md","filePath":"reference/changelog.md"}'),n={name:"reference/changelog.md"};function r(s,e,l,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[o('<h2 id="v0-6-0" tabindex="-1">v0.6.0 <a class="header-anchor" href="#v0-6-0" aria-label="Permalink to &quot;v0.6.0&quot;">​</a></h2><h3 id="multiple-admin-accounts" tabindex="-1">Multiple admin accounts <a class="header-anchor" href="#multiple-admin-accounts" aria-label="Permalink to &quot;Multiple admin accounts&quot;">​</a></h3><ul><li><strong>Admin accounts</strong> - Create and manage multiple admin accounts from the new Admins page. Each admin has a display name, email, and password. The currently signed-in admin is shown with a &quot;you&quot; indicator. Deleting your own account or the last remaining account is blocked.</li></ul><h3 id="reverse-proxy-integrations" tabindex="-1">Reverse proxy integrations <a class="header-anchor" href="#reverse-proxy-integrations" aria-label="Permalink to &quot;Reverse proxy integrations&quot;">​</a></h3><ul><li><strong>Nginx auth_request</strong> - Full configuration guide for protecting sites with nginx&#39;s <code>auth_request</code> module. See <a href="/integrations/nginx.html">Nginx auth_request</a>.</li><li><strong>Caddy forward_auth</strong> - Full Caddyfile guide for protecting sites with Caddy&#39;s <code>forward_auth</code> directive. See <a href="/integrations/caddy.html">Caddy forward_auth</a>.</li><li><strong>X-Auth-Groups header</strong> - The <code>/auth/verify</code> endpoint now returns an <code>X-Auth-Groups</code> header containing a comma-separated list of the authenticated user&#39;s group names. All three reverse proxy integrations (Traefik, Nginx, Caddy) forward this header to the upstream application.</li></ul><hr><h2 id="v0-5-0" tabindex="-1">v0.5.0 <a class="header-anchor" href="#v0-5-0" aria-label="Permalink to &quot;v0.5.0&quot;">​</a></h2><h3 id="social-login" tabindex="-1">Social login <a class="header-anchor" href="#social-login" aria-label="Permalink to &quot;Social login&quot;">​</a></h3><ul><li><strong>Social login</strong> - Sign in with GitHub, Google, or Discord. Enable each provider from Settings with an OAuth2 client ID and secret. A &quot;Continue with...&quot; button appears on the login page for each enabled provider. On first sign-in, GateKeeper auto-links the provider to an existing account if the email matches. Users can connect and disconnect providers from their profile page. See <a href="/admin/social-login.html">Social login</a>.</li></ul><h3 id="groups" tabindex="-1">Groups <a class="header-anchor" href="#groups" aria-label="Permalink to &quot;Groups&quot;">​</a></h3><ul><li><strong>Groups</strong> - Create named groups and assign users to them. Group membership is automatically included as a <code>groups</code> claim in all OIDC tokens, enabling role mapping in apps like Grafana and Jellyfin without any scope configuration. Manage group members from the Groups page or directly from a user&#39;s profile page. See <a href="/admin/groups.html">Groups</a> for Grafana and Jellyfin config examples.</li></ul><h3 id="user-self-registration" tabindex="-1">User self-registration <a class="header-anchor" href="#user-self-registration" aria-label="Permalink to &quot;User self-registration&quot;">​</a></h3><ul><li><strong>Registration modes</strong> - Choose between disabled, invite-only, open, and approval-required modes from Settings. In open mode anyone can create an account immediately. In approval mode accounts are held in a pending queue until an admin approves or rejects them from the Users page. A &quot;Create account&quot; link appears on the sign-in page when registration is open or approval-mode. Domain restrictions can limit which email domains are allowed to self-register. See <a href="/admin/registration.html">Registration</a>.</li></ul><h3 id="invite-links" tabindex="-1">Invite links <a class="header-anchor" href="#invite-links" aria-label="Permalink to &quot;Invite links&quot;">​</a></h3><ul><li><strong>Invite links</strong> - Generate single-use registration links from the Invites page. Each link can be tied to a specific email address (pre-filling and locking the registration form) or left open for any address. Links expire after 1, 3, 7, 14, or 30 days. The raw token is shown once at creation time; only a SHA-256 hash is stored. See <a href="/admin/invites.html">Invites</a>.</li></ul><h3 id="oidc-improvements" tabindex="-1">OIDC improvements <a class="header-anchor" href="#oidc-improvements" aria-label="Permalink to &quot;OIDC improvements&quot;">​</a></h3><ul><li><strong>RP-initiated logout</strong> - Signing out of an OIDC client (e.g., Grafana) now also clears the GateKeeper session cookie. The <code>post_logout_redirect_uri</code> parameter is honoured so users land back on the correct page.</li><li><strong>Token introspection</strong> - The <code>/oauth/introspect</code> endpoint (RFC 7662) is supported. APIs and services can verify bearer tokens server-side by calling the endpoint with their client credentials. See <a href="/admin/managing-clients.html">Managing clients</a>.</li><li><strong>Client credentials flow</strong> - Enable machine-to-machine auth per client by setting a list of allowed scopes on the client.</li><li><strong>Custom claims</strong> - Inject extra fields into tokens on a per-client basis. Map user ID, email, display name, group membership, or a literal string to any claim key. Manage from the claims icon on the OIDC Clients page. See <a href="/admin/custom-claims.html">Custom claims</a>. Services call <code>POST /oauth/token</code> with <code>grant_type=client_credentials</code> and receive an access token with <code>sub</code> set to the client ID. See <a href="/admin/managing-clients.html">Managing clients</a>.</li></ul><h3 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h3><ul><li><strong>Live stats</strong> - The sign-ins, failed attempts, and OIDC token counts on the dashboard now refresh every 30 seconds without a full page reload.</li></ul><hr><h2 id="v0-4-0" tabindex="-1">v0.4.0 <a class="header-anchor" href="#v0-4-0" aria-label="Permalink to &quot;v0.4.0&quot;">​</a></h2><h3 id="security-hardening" tabindex="-1">Security hardening <a class="header-anchor" href="#security-hardening" aria-label="Permalink to &quot;Security hardening&quot;">​</a></h3><ul><li><strong>AES-256-GCM for TOTP secrets</strong> - TOTP secrets are now encrypted with AES-256-GCM before storage. The encryption key is derived from <code>SECRET_KEY</code> using SHA-256. Existing secrets encrypted with the older XOR scheme are migrated automatically on next login - no action required.</li><li><strong>HMAC-SHA256 for OTP codes</strong> - Email OTP codes are no longer stored as plaintext. They are stored as HMAC-SHA256 digests keyed with <code>SECRET_KEY</code>. A database dump without the key cannot reconstruct active codes.</li><li><strong>CSRF protection on all user endpoints</strong> - All authenticated state-changing POST requests (password change, 2FA enrollment, session revocation, passkey deletion, name and avatar update) now validate a CSRF token. Previously only the admin panel validated CSRF.</li><li><strong>Login rate limiting</strong> - The login endpoint now enforces an IP-based rate limit of 20 failed attempts per 15-minute window. Excess attempts receive an error before any password check.</li><li><strong>OTP issuance rate limit</strong> - Each user can request at most 3 OTP codes per 10-minute window, preventing email flooding.</li><li><strong>Tightened Content-Security-Policy</strong> - Added <code>object-src &#39;none&#39;</code>, <code>base-uri &#39;self&#39;</code>, <code>connect-src &#39;self&#39;</code>, and <code>frame-ancestors &#39;none&#39;</code>. Added <code>https://www.gravatar.com</code> to <code>img-src</code>.</li></ul><h3 id="user-home-redesign" tabindex="-1">User home redesign <a class="header-anchor" href="#user-home-redesign" aria-label="Permalink to &quot;User home redesign&quot;">​</a></h3><ul><li><strong>New user home layout</strong> - The authenticated home page (<code>/</code>) is fully redesigned. It shows a header with the GateKeeper logo, email, and theme toggle; a page head with avatar, display name, and inline name edit; three stat cards (sign-in methods, passkeys, sessions); a sign-in methods card; a passkeys card; and an active sessions card.</li><li><strong>Session management</strong> - Users can view all active sessions (device, browser, IP, last seen, time ago) and revoke individual sessions or all sessions except the current one directly from the home page.</li></ul><h2 id="v0-3-0" tabindex="-1">v0.3.0 <a class="header-anchor" href="#v0-3-0" aria-label="Permalink to &quot;v0.3.0&quot;">​</a></h2><ul><li><strong>Webhooks</strong> - Send push notifications to Discord, Slack, Telegram, ntfy (public and self-hosted), generic JSON endpoints, or email when auth and admin events occur. Configure per-webhook event subscriptions and test delivery inline from the Webhooks page.</li><li><strong>Access policies</strong> - Create named policies and assign users to them. Attach a policy to an OIDC client to restrict which users can complete authorization, or reference it via <code>?policy=&lt;name&gt;</code> on <code>/auth/verify</code> for ForwardAuth routes. Policy ForwardAuth URL shown with copy button on the policies page.</li><li><strong>Admin audit logging</strong> - Admin sign-in (password and passkey), sign-out, failed login attempts, and user deletion are now recorded in the audit log alongside all other events.</li><li><strong>Audit log retention</strong> - Set a retention period in Settings. Events older than the configured number of days are deleted automatically on startup and daily. Default is 90 days; set to 0 to keep all events.</li><li><strong>Audit log date filter</strong> - Filter by Today, 7 days, 30 days, 90 days, or All time directly from the toolbar.</li><li><strong>User profile</strong> - Users can set a display name and pull in a Gravatar avatar from their home screen. The image is fetched server-side and cached in the database so the browser never contacts Gravatar directly.</li><li><strong>Avatars everywhere</strong> - Display name and avatar appear in the admin user list, user detail page, audit log rows, and dashboard recent events.</li><li><strong>Dashboard redesign</strong> - Real sparklines from the database on the sign-ins, failed attempts, and OIDC traffic cards. New cards for active sessions, 2FA adoption, and audit log stats. Auth methods card with 24h / 7d / 30d range toggle.</li><li><strong>Command palette fixes</strong> - <code>⌘K</code> / <code>Ctrl+K</code> palette now has working keyboard navigation (arrow keys, Enter). All pages including Policies, Webhooks, and Integrations appear in the navigate list. Searching users matches display name in addition to email.</li><li><strong>New user modal</strong> - Creating a user from the Users page now opens an inline modal instead of navigating to a separate page.</li><li><strong>Policies table</strong> - Policies page redesigned to match the OIDC clients table layout with description, member count, and used-by columns.</li><li><strong>System health section</strong> - Consolidates configuration warnings (locked accounts, users without 2FA, OIDC signing key status).</li></ul><h2 id="v0-2-0" tabindex="-1">v0.2.0 <a class="header-anchor" href="#v0-2-0" aria-label="Permalink to &quot;v0.2.0&quot;">​</a></h2><ul><li><strong>OIDC provider</strong> - Full authorization code + PKCE flow. Apps can now use GateKeeper as a proper OIDC identity provider (Traefik Manager, Termix, Grafana, Jellyfin, etc.)</li><li><strong>OIDC client icons</strong> - Add an icon URL per client. Icons are fetched and cached server-side at save time; the login page loads them from GateKeeper, not external servers.</li><li><strong>Login page branding</strong> - When signing in via OIDC, the login page shows the app name and cached icon instead of the GateKeeper logo.</li><li><strong>Client editing</strong> - Edit name, icon, redirect URIs, and optionally rotate the secret of any OIDC client without deleting and recreating it.</li><li><strong>OIDC endpoint reference</strong> - The clients page now shows all endpoint URLs (authorization, token, userinfo, JWKS, discovery) with copy buttons.</li><li><strong>Secret generator</strong> - One-click cryptographically random secret generation in the new/edit client dialogs.</li><li><strong>Trusted device tokens</strong> - After passing 2FA, a 30-day <code>gk_trust</code> cookie is set. Users on trusted devices skip the second factor until it expires.</li><li><strong>Cross-domain ForwardAuth</strong> - HMAC-signed short-lived tokens allow GateKeeper to set per-host cookies for apps on different TLDs.</li><li><strong>Interactive dashboard chart</strong> - Sign-in activity chart with 24h / 7d / 30d range toggle and hover tooltips backed by real data.</li><li><strong>Real auth method breakdown</strong> - Dashboard shows live percentages for passkey, TOTP, email OTP, and OIDC logins in the last 24 hours.</li><li><strong>Command palette</strong> - <code>⌘K</code> / <code>Ctrl+K</code> opens a search palette. Type to search users and clients by name. Keyboard shortcuts <code>g d/u/c/a/s</code> navigate between sections.</li><li><strong>Audit log improvements</strong> - Event type filter chips (auth / admin / oidc), kind filter (success / warn / fail / info), per-row filter button, correct event count.</li><li><strong>Mobile navigation</strong> - Bottom navigation bar on screens under 760px.</li><li><strong>Admin sidebar</strong> - Live user and client counts, version number in the footer.</li><li><strong>New user sign-in methods</strong> - Create users as &quot;Email + Password&quot; or &quot;Email Only&quot; (passwordless) directly from the new user form.</li><li><strong>OIDC post-login redirect</strong> - After authenticating via OIDC, GateKeeper correctly completes the auth request and redirects back to the app with an authorization code.</li><li><strong>Theme persistence</strong> - Dark/light/auto preference now survives full page navigation (was blocked by CSP preventing the inline bootstrap script).</li></ul><h2 id="v0-1-0" tabindex="-1">v0.1.0 <a class="header-anchor" href="#v0-1-0" aria-label="Permalink to &quot;v0.1.0&quot;">​</a></h2><p>Initial release.</p><ul><li>Password + email OTP login</li><li>Passwordless email OTP mode (per-user, admin-configurable)</li><li>TOTP enrollment with QR code and recovery codes</li><li>Passkey (WebAuthn) registration and authentication</li><li>Password recovery via email with rate-limited, single-use tokens</li><li>Authenticated password change with session invalidation</li><li>Forced password change on admin-created accounts</li><li>Traefik ForwardAuth middleware (<code>/auth/verify</code>)</li><li>OIDC provider with authorization code + PKCE flow</li><li>OIDC scopes: <code>openid</code>, <code>email</code>, <code>profile</code>, <code>offline_access</code></li><li>RS256 signing with 30-day key rotation</li><li>First-run setup page at <code>/admin/setup</code> - no env vars needed for admin credentials</li><li>Admin UI for user and OIDC client management</li><li>Admin profile page - change password, enroll TOTP, register passkeys</li><li>All runtime settings (SMTP, session TTL, allowed domains) configurable in the admin UI</li><li>Append-only audit log</li><li>SQLite persistence with embedded migrations</li><li>Docker multi-stage build (golang:1.26-alpine)</li><li>Astro Starlight documentation site</li></ul>',32)])])}const p=a(n,[["render",r]]);export{u as __pageData,p as default};
